function setView(view='dashboard'){if(pageContent)pageContent.dataset.viewMode=view==='dashboard'?'dashboard':'detail';document.querySelectorAll('[data-view-panel]').forEach(el=>{el.classList.toggle('view-hidden',view!=='dashboard'&&el.dataset.viewPanel!==view);});const settings=document.querySelector('#settings');if(settings){settings.dataset.activeView=view;if(view==='telegram'||view==='sip')settings.classList.remove('view-hidden');}if(lowerGrid)lowerGrid.classList.toggle('view-hidden',view!=='dashboard'&&view!=='calls');if(setupPanel)setupPanel.classList.toggle('view-hidden',view!=='dashboard');document.querySelectorAll('.nav-item').forEach(nav=>nav.classList.toggle('active',(nav.dataset.view||'dashboard')===view));const labels={dashboard:'Genel Bakış',calls:'Çağrılar',appointments:'Randevular',agents:'AI Ajanları','opening-message':'Açılış mesajı',customers:'Müşteriler',sip:'SIP Bağlantıları',knowledge:'Bilgi Bankası',telegram:'Telegram',settings:'Ayarlar',help:'Yardım Merkezi'};const crumb=document.querySelector('.breadcrumb strong');if(crumb)crumb.textContent=labels[view]||'Genel Bakış';if(location.hash!==`#${view}`)history.replaceState(null,'',`#${view}`);}
