const loginScreen = document.querySelector('#login-screen');
const loginForm = document.querySelector('#login-form');
const loginError = document.querySelector('#login-error');
async function checkSession() {
  try { const response = await fetch('/api/me', {credentials:'same-origin'}); if (response.ok) { const data=await response.json(); applyUser(data.user); loginScreen.classList.add('hidden'); loadOperationalData(); } } catch (_) {}
}
loginForm?.addEventListener('submit', async (event) => {
  event.preventDefault(); loginError.textContent = '';
  const payload = Object.fromEntries(new FormData(loginForm).entries());
  try {
    const response = await fetch('/api/login', {method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin', body:JSON.stringify(payload)});
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || 'Giriş yapılamadı');
    applyUser(data.user); loginScreen.classList.add('hidden');
    loadOperationalData();
  } catch (error) { loginError.textContent = error.message; }
});
checkSession();
const providerForm = document.querySelector('#provider-form');
const providerStatus = document.querySelector('#provider-status');
async function loadProviders() {
  try { const r = await fetch('/api/admin/providers', {credentials:'same-origin'}); if (!r.ok) return; const d = await r.json(); const active = d.items.find(x => x.enabled) || d.items[0]; if (active) { document.querySelector('#provider-name').value = active.provider; document.querySelector('#provider-model').value = active.model || ''; document.querySelector('#provider-enabled').checked = active.enabled; providerStatus.textContent = active.configured ? `Kayıtlı anahtar: ${active.masked}` : 'Anahtar tanımlı değil'; } } catch (_) {}
}
providerForm?.addEventListener('submit', async (event) => { event.preventDefault(); providerStatus.textContent = 'Kaydediliyor…'; const payload = {provider:document.querySelector('#provider-name').value, model:document.querySelector('#provider-model').value, api_key:document.querySelector('#provider-key').value, enabled:document.querySelector('#provider-enabled').checked}; try { const r = await fetch('/api/admin/providers',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)}); const d = await r.json(); if (!r.ok) throw new Error(d.error); document.querySelector('#provider-key').value=''; providerStatus.textContent = `Kaydedildi (${d.provider.masked || 'anahtar yok'})`; } catch (e) { providerStatus.textContent = e.message || 'Kayıt başarısız'; } });
loadProviders();
function escapeHtml(value='') { return String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function applyUser(user) { currentUser=user||null; document.body.dataset.role=user?.role||'guest'; document.querySelectorAll('[data-admin-only]').forEach(el=>{el.hidden=user?.role!=='admin';}); document.querySelectorAll('[data-customer-only]').forEach(el=>{el.hidden=user?.role!=='customer';}); const tenantName=document.querySelector('.tenant-copy strong'); const tenantMeta=document.querySelector('.tenant-copy small'); const tenantAvatar=document.querySelector('.tenant-avatar'); const greeting=document.querySelector('.welcome-row h1'); const setupName=document.querySelector('#setup-tenant-name'); const agentName=document.querySelector('.agents-panel .agent-info strong'); const callTenant=document.querySelector('#calls tbody'); if(user?.role==='admin'){if(tenantName)tenantName.textContent='OIM SaaS';if(tenantMeta)tenantMeta.textContent='Yönetici paneli';if(tenantAvatar)tenantAvatar.textContent='OI'; if(greeting)greeting.textContent='Günaydın, AI Call Center'; if(location.hash==='#knowledge')setView('dashboard');}else if(user){const displayName=user.name||'Müşteri';if(tenantName)tenantName.textContent=displayName;if(tenantMeta)tenantMeta.textContent='Müşteri hesabı';if(tenantAvatar)tenantAvatar.textContent=String(displayName).split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();if(greeting)greeting.textContent=`Günaydın, ${displayName}`;if(setupName)setupName.textContent=`${displayName} sesli ajanı`;if(agentName)agentName.textContent=displayName;if(['#sip','#settings'].includes(location.hash))setView('dashboard');} }
function formatMoment(value) { if (!value) return '—'; const d = typeof value === 'number' ? new Date(value * 1000) : new Date(value); return Number.isNaN(d.getTime()) ? escapeHtml(value) : new Intl.DateTimeFormat('tr-TR',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Istanbul'}).format(d); }
function formatDuration(start,end) { if (!start) return '—'; const seconds=Math.max(0,(end||Math.floor(Date.now()/1000))-start); return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`; }
const todayLabel=document.querySelector('#today-label'); if(todayLabel)todayLabel.textContent=new Intl.DateTimeFormat('tr-TR',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Istanbul'}).format(new Date()).toLocaleUpperCase('tr-TR');
async function loadOperationalData() {
  try {
    const tenantQuery=currentUser?.role==='admin'?`?tenant_id=${encodeURIComponent(dashboardTenantId)}`:'';
    const [meResponse,callsResponse,appointmentsResponse]=await Promise.all([fetch('/api/me',{credentials:'same-origin'}),fetch(`/api/calls${tenantQuery}`,{credentials:'same-origin'}),fetch(`/api/appointments${tenantQuery}`,{credentials:'same-origin'})]);
    let balance=0;
    if(meResponse.ok){const me=await meResponse.json(); applyUser(me.user); balance=Number(me.user?.credits||0); if(me.user?.role==='admin'){const tenantsResponse=await fetch('/api/admin/tenants',{credentials:'same-origin'}); if(tenantsResponse.ok){const tenants=await tenantsResponse.json(); const selected=tenants.items.find(x=>Number(x.id)===Number(dashboardTenantId))||tenants.items[0]; if(selected){dashboardTenantId=Number(selected.id); balance=Number(selected.credits||0); const picker=document.querySelector('#dashboard-tenant'); if(picker){picker.innerHTML=tenants.items.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join(''); picker.value=String(dashboardTenantId);} const setupName=document.querySelector('#setup-tenant-name'); if(setupName)setupName.textContent=`${selected.name} sesli ajanı`;} loadCustomers(tenants.items);}}}
    if (callsResponse.ok) {
      const {items:rawItems=[]}=await callsResponse.json(); const cutoff=Math.floor(Date.now()/1000)-(trafficRangeDays*86400); const items=rawItems.filter(x=>!x.started_at||Number(x.started_at)>=cutoff); const body=document.querySelector('#calls tbody');
      if (body) body.innerHTML=items.length?items.map((call)=>{const rejected=call.status==='rejected_no_credit';const failed=call.status==='failed';const label=call.status==='active'?'Aktif':rejected?'Kredi yetersiz':failed?'Hata':'Tamamlandı';return `<tr><td><div class="caller"><span class="mini-avatar">AI</span><strong>${escapeHtml(call.caller||'Telefon araması')}</strong></div></td><td>${escapeHtml(call.caller||'Gizli numara')}</td><td>${escapeHtml(currentUser?.role==='admin'?'Seçili müşteri':(currentUser?.name||'Müşteri'))}</td><td>${formatDuration(call.started_at,call.ended_at)}</td><td>${Number(call.billed_credits||0).toFixed(2)}</td><td><span class="pill ${failed||rejected?'warning':'success'}">${escapeHtml(label)}</span></td></tr>`;}).join(''):'<tr><td colspan="6">Henüz gerçek çağrı kaydı yok.</td></tr>';
      const completed=items.filter(x=>x.status==='ended'); const seconds=completed.reduce((sum,x)=>sum+Math.max(0,(x.ended_at||x.started_at)-x.started_at),0); const average=completed.length?Math.round(seconds/completed.length):0;
      document.querySelector('#metric-calls').textContent=String(items.length); document.querySelector('#metric-completed').textContent=String(completed.length); document.querySelector('#metric-duration').textContent=`${String(Math.floor(average/60)).padStart(2,'0')}:${String(average%60).padStart(2,'0')}`; document.querySelector('#metric-credits').textContent=balance.toFixed(2);
      const metered=items.filter(x=>Number.isFinite(Number(x.estimated_openai_usd))); const usd=metered.reduce((sum,x)=>sum+(Number(x.estimated_openai_usd)||0),0); const tokens=metered.reduce((sum,x)=>sum+(Number(x.total_tokens)||0),0); const usdEl=document.querySelector('#metric-openai-usd'); const tokenEl=document.querySelector('#metric-total-tokens'); const callsEl=document.querySelector('#metric-metered-calls'); if(usdEl)usdEl.textContent=`$${usd.toFixed(4)}`; if(tokenEl)tokenEl.textContent=tokens.toLocaleString('tr-TR'); if(callsEl)callsEl.textContent=String(metered.length);
      document.querySelector('#nav-call-count').textContent=String(items.length); const agentCalls=document.querySelector('.agent-row .agent-calls'); if(agentCalls)agentCalls.textContent=`${items.length} çağrı`;
    }
    if (appointmentsResponse.ok) {
      const {items=[]}=await appointmentsResponse.json(); const body=document.querySelector('#appointments-body');
      if (body) body.innerHTML=items.length?items.map((item)=>`<tr><td><strong>${formatMoment(item.appointment_at)}</strong></td><td>${escapeHtml(item.customer_name)}</td><td>${escapeHtml(item.phone)}</td><td>${escapeHtml(item.service)}</td><td><span class="pill success">${item.status==='confirmed'?'Onaylandı':escapeHtml(item.status)}</span></td></tr>`).join(''):'<tr><td colspan="5">Henüz randevu yok.</td></tr>';
      renderCalendar(items);
    }
  } catch (_) {}
  loadProviders(); loadSip(); loadTelegram(); loadCustomerTelegram(); loadContacts(); loadGoogleCalendar(); loadKnowledge();
}

