const settingsPanel=document.querySelector('#settings'); let creditTenantId=0;
if(settingsPanel){const creditBlock=document.createElement('div'); creditBlock.innerHTML='<div class="panel-heading"><div><h2>Kredi yönetimi</h2><p>Aktif müşteriyi seçin; kredi bakiyesine ekleme veya düzeltme yapın.</p></div><span class="pill success">SaaS yönetimi</span></div><form id="credit-form" class="provider-form"><label>Müşteri<select id="credit-tenant" required><option value="">Henüz müşteri yok</option></select></label><label>Kredi miktarı<input id="credit-amount" type="number" step="0.01" required placeholder="100"></label><label>Açıklama<input id="credit-reason" value="Manuel kredi tanımı" required></label><button class="button primary" type="submit">Krediyi uygula</button><span id="credit-status" class="form-note"></span></form><div class="billing-rate-box"><div class="panel-heading"><div><h3>Kullanım tarifesi</h3><p>Çağrı kapanırken dakika bazında kredi düşümü uygulanır.</p></div></div><form id="billing-form" class="provider-form"><label>Kredi / dakika<input id="billing-rate" type="number" min="0" step="0.01" required></label><label>AI çarpanı<input id="billing-multiplier" type="number" min="0" step="0.01" required></label><label>Sunucu / saat<input id="billing-server" type="number" min="0" step="0.01" required></label><button class="button secondary" type="submit">Tarifeyi kaydet</button><span id="billing-status" class="form-note"></span></form></div><hr>'; settingsPanel.insertBefore(creditBlock,settingsPanel.firstChild);}
if(settingsPanel){const legalBlock=document.createElement('div');legalBlock.id='legal-settings';legalBlock.innerHTML='<div class="panel-heading"><div><h2>Sözleşme, KVKK ve e-posta</h2><p>Müşteri kaydı için sözleşme/KVKK metinlerini ve hoş geldin e-postası SMTP bağlantısını yönetin.</p></div><span class="pill success">Yönetici</span></div><form id="legal-form" class="provider-form"><label>Kullanıcı sözleşmesi<textarea id="agreement-text" rows="6" required placeholder="Müşterinin kabul edeceği kullanıcı sözleşmesi"></textarea></label><label>KVKK aydınlatma metni<textarea id="kvkk-text" rows="6" required placeholder="KVKK aydınlatma metni"></textarea></label><div class="form-grid"><label>SMTP sunucusu<input id="smtp-host" placeholder="smtp.example.com"></label><label>Port<input id="smtp-port" type="number" min="1" max="65535" value="587"></label><label>SMTP kullanıcı adı<input id="smtp-user" autocomplete="off"></label><label>Gönderen e-posta<input id="smtp-from" type="email" placeholder="info@example.com"></label></div><label>SMTP parolası<input id="smtp-password" type="password" autocomplete="new-password" placeholder="Değiştirmek için girin"></label><button class="button primary" type="submit">Metin ve e-posta ayarlarını kaydet</button><span id="legal-status" class="form-note"></span></form><hr>';settingsPanel.insertBefore(legalBlock,settingsPanel.firstChild);}
async function loadLegalSettings(){try{const r=await fetch('/api/admin/legal-settings',{credentials:'same-origin'});if(!r.ok)return;const d=await r.json();document.querySelector('#agreement-text').value=d.user_agreement||'';document.querySelector('#kvkk-text').value=d.kvkk_text||'';document.querySelector('#smtp-host').value=d.smtp_host||'';document.querySelector('#smtp-port').value=d.smtp_port||587;document.querySelector('#smtp-user').value=d.smtp_username||'';document.querySelector('#smtp-from').value=d.smtp_from||'';document.querySelector('#legal-status').textContent=d.smtp_password_configured?'SMTP parolası kayıtlı.':'SMTP parolası tanımlı değil.';}catch(_){} }
document.querySelector('#legal-form')?.addEventListener('submit',async(e)=>{e.preventDefault();const status=document.querySelector('#legal-status');status.textContent='Kaydediliyor…';const payload={user_agreement:document.querySelector('#agreement-text').value,kvkk_text:document.querySelector('#kvkk-text').value,smtp_host:document.querySelector('#smtp-host').value,smtp_port:Number(document.querySelector('#smtp-port').value||587),smtp_username:document.querySelector('#smtp-user').value,smtp_from:document.querySelector('#smtp-from').value,smtp_password:document.querySelector('#smtp-password').value};try{const r=await fetch('/api/admin/legal-settings',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.error);document.querySelector('#smtp-password').value='';status.textContent=d.smtp_password_configured?'Ayarlar kaydedildi; SMTP parolası korumalı.':'Metinler kaydedildi; SMTP parolası henüz tanımlı değil.';}catch(err){status.textContent=err.message||'Ayarlar kaydedilemedi';}});loadLegalSettings();
async function loadBilling(){try{const r=await fetch('/api/admin/billing',{credentials:'same-origin'});if(!r.ok)return;const d=await r.json();document.querySelector('#billing-rate').value=d.credits_per_minute??1;document.querySelector('#billing-multiplier').value=d.ai_multiplier??1;document.querySelector('#billing-server').value=d.server_hourly_rate??0;}catch(_){} }
