document.querySelector('#billing-form')?.addEventListener('submit',async(e)=>{e.preventDefault();const status=document.querySelector('#billing-status');status.textContent='Kaydediliyor…';try{const payload={credits_per_minute:Number(document.querySelector('#billing-rate').value),ai_multiplier:Number(document.querySelector('#billing-multiplier').value),server_hourly_rate:Number(document.querySelector('#billing-server').value)};const r=await fetch('/api/admin/billing',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.error);status.textContent='Kullanım tarifesi kaydedildi.';}catch(err){status.textContent=err.message||'Tarife kaydedilemedi';}});
if(settingsPanel){const ledgerBlock=document.createElement('div'); ledgerBlock.innerHTML='<div class="panel-heading"><div><h2>Kredi hareketleri</h2><p>Müşteri bazında kredi yükleme ve kullanım dökümleri.</p></div><span class="pill success">Son 200 işlem</span></div><div class="ledger-toolbar"><label>Müşteri<select id="ledger-tenant"><option value="">Henüz müşteri yok</option></select></label><label>Tür<select id="ledger-kind"><option value="">Tümü</option><option value="credit">Kredi</option><option value="debit">Kullanım</option></select></label><button class="button secondary" id="ledger-export" type="button">CSV indir</button></div><div class="table-wrap"><table><thead><tr><th>TARİH</th><th>TÜR</th><th>TUTAR</th><th>AÇIKLAMA</th></tr></thead><tbody id="ledger-body"><tr><td colspan="4">Hareketler yükleniyor…</td></tr></tbody></table></div><hr>'; settingsPanel.insertBefore(ledgerBlock,settingsPanel.firstChild);}
let ledgerItems=[];
async function loadLedger(){const body=document.querySelector('#ledger-body');if(!body)return;const tid=document.querySelector('#ledger-tenant')?.value||'2';const kind=document.querySelector('#ledger-kind')?.value||'';try{const r=await fetch(`/api/ledger?tenant_id=${encodeURIComponent(tid)}&kind=${encodeURIComponent(kind)}`,{credentials:'same-origin'});const d=await r.json();if(!r.ok)throw Error(d.error);ledgerItems=d.items||[];body.innerHTML=ledgerItems.length?ledgerItems.map(x=>`<tr><td>${formatMoment(x.created_at)}</td><td><span class="pill ${x.kind==='credit'?'success':'warning'}">${x.kind==='credit'?'Kredi':'Kullanım'}</span></td><td class="ledger-amount ${x.amount<0?'negative':'positive'}">${x.amount>0?'+':''}${Number(x.amount).toFixed(2)}</td><td>${escapeHtml(x.reason||'—')}</td></tr>`).join(''):'<tr><td colspan="4">Bu müşteri için hareket yok.</td></tr>';}catch(err){body.innerHTML=`<tr><td colspan="4">${escapeHtml(err.message||'Hareketler alınamadı')}</td></tr>`;}}
document.querySelector('#ledger-tenant')?.addEventListener('change',loadLedger); document.querySelector('#ledger-kind')?.addEventListener('change',loadLedger); loadLedger();
document.querySelector('#ledger-export')?.addEventListener('click',()=>{const rows=[['Tarih','Tür','Tutar','Açıklama'],...ledgerItems.map(x=>[formatMoment(x.created_at),x.kind==='credit'?'Kredi':'Kullanım',Number(x.amount).toFixed(2),x.reason||''])];const csv='\\ufeff'+rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(';')).join('\\r\\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='oim-kredi-hareketleri.csv';a.click();URL.revokeObjectURL(a.href);});
document.querySelector('#credit-tenant')?.addEventListener('change',(e)=>{creditTenantId=Number(e.target.value);});
document.querySelector('#credit-form')?.addEventListener('submit',async(e)=>{e.preventDefault(); const status=document.querySelector('#credit-status'); status.textContent='Uygulanıyor…'; try{const amount=Number(document.querySelector('#credit-amount').value); const reason=document.querySelector('#credit-reason').value; if(!Number.isFinite(amount)||amount===0)throw Error('Sıfırdan farklı bir kredi miktarı girin.'); const r=await fetch(`/api/admin/tenants/${creditTenantId}/credits`,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({amount,reason})}); const d=await r.json(); if(!r.ok)throw Error(d.error); status.textContent=`${d.tenant.name}: yeni bakiye ${Number(d.tenant.credits).toFixed(2)} kredi`; document.querySelector('#credit-amount').value=''; loadOperationalData();}catch(err){status.textContent=err.message||'Kredi işlemi başarısız';}});

if(settingsPanel){const telegramBlock=document.createElement('div'); telegramBlock.id='telegram'; telegramBlock.dataset.viewPanel='telegram'; telegramBlock.innerHTML='<div class="panel-heading"><div><h2>Telegram çağrı kayıtları</h2><p>Gelen çağrı kayıtlarını belirlediğiniz özel gruba otomatik gönderir.</p></div></div><form id="telegram-form" class="provider-form"><label>Bot tokeni<input id="telegram-token" type="password" autocomplete="new-password" placeholder="Değiştirmek için girin"></label><label>Grup Chat ID<input id="telegram-chat" placeholder="-100..."></label><label class="check"><input id="telegram-enabled" type="checkbox"> Kayıt gönderimini etkinleştir</label><button class="button primary" type="submit">Telegram ayarlarını kaydet</button><span id="telegram-status" class="form-note"></span></form><hr>'; settingsPanel.insertBefore(telegramBlock,settingsPanel.firstChild);}
async function loadTelegram(){try{const r=await fetch('/api/admin/telegram',{credentials:'same-origin'}); if(!r.ok)return; const d=await r.json(); document.querySelector('#telegram-chat').value=d.chat_id||''; document.querySelector('#telegram-enabled').checked=Boolean(d.enabled); document.querySelector('#telegram-status').textContent=d.configured?`Kayıtlı token: ${d.masked}`:'Telegram botu tanımlı değil';}catch(_){}}
document.querySelector('#telegram-form')?.addEventListener('submit',async(e)=>{e.preventDefault(); const status=document.querySelector('#telegram-status'); status.textContent='Doğrulanıyor…'; const payload={bot_token:document.querySelector('#telegram-token').value,chat_id:document.querySelector('#telegram-chat').value,enabled:document.querySelector('#telegram-enabled').checked}; try{const r=await fetch('/api/admin/telegram',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)}); const d=await r.json(); if(!r.ok)throw Error(d.error); document.querySelector('#telegram-token').value=''; status.textContent=`@${d.bot_username} kaydedildi (${d.masked})`;}catch(err){status.textContent=err.message||'Telegram ayarı kaydedilemedi';}});
let crmItems=[]; function renderContacts(){const body=document.querySelector('#contacts-body');if(!body)return;const qName=(document.querySelector('#crm-filter')?.value||'').trim().toLocaleLowerCase('tr-TR');const qPhone=(document.querySelector('#crm-phone-filter')?.value||'').trim().toLocaleLowerCase('tr-TR');const qEmail=(document.querySelector('#crm-email-filter')?.value||'').trim().toLocaleLowerCase('tr-TR');const items=crmItems.filter(x=>(!qName||String(x.name||'').toLocaleLowerCase('tr-TR').includes(qName))&&(!qPhone||String(x.phone||'').toLocaleLowerCase('tr-TR').includes(qPhone))&&(!qEmail||String(x.email||'').toLocaleLowerCase('tr-TR').includes(qEmail)));body.innerHTML=items.length?items.map(x=>'<tr><td><strong>'+escapeHtml(x.name)+'</strong></td><td>'+escapeHtml(x.phone||'—')+'</td><td>'+escapeHtml(x.email||'—')+'</td><td>'+escapeHtml(x.notes||'—')+'</td><td><div class="crm-actions"><button class="button outline" type="button" data-edit-contact="'+x.id+'">Düzenle</button><button class="button secondary" type="button" data-delete-contact="'+x.id+'">Sil</button></div></td></tr>').join(''):'<tr><td colspan="5">'+(crmItems.length?'Filtreye uygun müşteri yok.':'Henüz CRM kaydı yok.')+'</td></tr>';} async function loadContacts(){const body=document.querySelector('#contacts-body');if(!body)return;try{const r=await fetch('/api/contacts',{credentials:'same-origin'});if(!r.ok)return;const d=await r.json();crmItems=d.items||[];renderContacts();}catch(_){}} document.querySelector('#crm-filter')?.addEventListener('input',renderContacts);document.querySelector('#crm-filter-clear')?.addEventListener('click',()=>{['#crm-filter','#crm-phone-filter','#crm-email-filter'].forEach(sel=>{const f=document.querySelector(sel);if(f)f.value='';});renderContacts();});document.querySelector('#crm-phone-filter')?.addEventListener('input',renderContacts);document.querySelector('#crm-email-filter')?.addEventListener('input',renderContacts);document.querySelector('#crm-export')?.addEventListener('click',()=>{const qName=(document.querySelector('#crm-filter')?.value||'').trim().toLocaleLowerCase('tr-TR');const qPhone=(document.querySelector('#crm-phone-filter')?.value||'').trim().toLocaleLowerCase('tr-TR');const qEmail=(document.querySelector('#crm-email-filter')?.value||'').trim().toLocaleLowerCase('tr-TR');const items=crmItems.filter(x=>(!qName||String(x.name||'').toLocaleLowerCase('tr-TR').includes(qName))&&(!qPhone||String(x.phone||'').toLocaleLowerCase('tr-TR').includes(qPhone))&&(!qEmail||String(x.email||'').toLocaleLowerCase('tr-TR').includes(qEmail)));const rows=[['Ad Soyad','Telefon','E-posta','Not'],...items.map(x=>[x.name||'',x.phone||'',x.email||'',x.notes||''])];const csv='\\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\\r\\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='oim-crm.xls';a.click();URL.revokeObjectURL(a.href);});
document.querySelector('#customer-telegram-form')?.addEventListener('submit',async(e)=>{e.preventDefault(); const status=document.querySelector('#customer-telegram-status'); status.textContent='Doğrulanıyor…'; const payload={bot_token:document.querySelector('#customer-telegram-token').value,chat_id:document.querySelector('#customer-telegram-chat').value,enabled:document.querySelector('#customer-telegram-enabled').checked}; try{const r=await fetch('/api/tenant/telegram',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)}); const d=await r.json(); if(!r.ok)throw Error(d.error); document.querySelector('#customer-telegram-token').value=''; status.textContent=`@${d.bot_username} bağlandı (${d.masked})`;}catch(err){status.textContent=err.message||'Telegram ayarı kaydedilemedi';}});
document.querySelector('#contact-form')?.addEventListener('submit',async(e)=>{e.preventDefault(); const status=document.querySelector('#contact-status'); status.textContent='Kaydediliyor…'; const payload={name:document.querySelector('#contact-name').value,phone:document.querySelector('#contact-phone').value,email:document.querySelector('#contact-email').value,notes:document.querySelector('#contact-notes').value}; try{const r=await fetch('/api/contacts',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)}); const d=await r.json(); if(!r.ok)throw Error(d.error); e.target.reset(); status.textContent='CRM kaydı eklendi.'; loadContacts();}catch(err){status.textContent=err.message||'CRM kaydı eklenemedi';}});
document.querySelector('#contacts-body')?.addEventListener('click',async(e)=>{const button=e.target.closest('[data-delete-contact],[data-edit-contact]');if(!button)return;const id=Number(button.dataset.deleteContact||button.dataset.editContact);const item=crmItems.find(x=>Number(x.id)===id);if(!item)return;if(button.dataset.deleteContact){if(!confirm('Bu CRM kaydı silinsin mi?'))return;const r=await fetch('/api/contacts/'+id+'/delete',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:'{}'});if(r.ok){showToast('CRM kaydı silindi.');loadContacts();}return;}const name=prompt('Ad soyad',item.name)||item.name;const phone=prompt('Telefon',item.phone||'')??item.phone;const email=prompt('E-posta',item.email||'')??item.email;const notes=prompt('Not',item.notes||'')??item.notes;const r=await fetch('/api/contacts/'+id+'/update',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({name,phone,email,notes})});if(r.ok){showToast('CRM kaydı güncellendi.');loadContacts();}else{showToast('CRM kaydı güncellenemedi.');}});
async function loadGoogleCalendar(){const status=document.querySelector('#google-status'); if(!status)return; try{const r=await fetch('/api/google/status',{credentials:'same-origin'}); const d=await r.json(); if(!d.configured){status.textContent='Google OAuth yönetici tarafından henüz yapılandırılmadı.';return;} status.textContent=d.connected?'Google Calendar bağlı. Dolu saatler korunuyor.':'Google Calendar bağlı değil.';}catch(_){status.textContent='Takvim durumu alınamadı.';}}
document.querySelector('#google-connect')?.addEventListener('click',async()=>{const status=document.querySelector('#google-status'); status.textContent='Google bağlantısı hazırlanıyor…'; try{const r=await fetch('/api/google/start',{credentials:'same-origin'}); const d=await r.json(); if(!r.ok)throw Error(d.error); location.href=d.url;}catch(err){status.textContent=err.message||'Google bağlantısı başlatılamadı';}});
async function loadKnowledge(){const body=document.querySelector('#knowledge-body'); if(!body)return; try{const r=await fetch('/api/knowledge',{credentials:'same-origin'}); if(!r.ok)return; const d=await r.json(); body.innerHTML=d.items.length?d.items.map(x=>`<tr><td>${escapeHtml(x.language.toUpperCase())}</td><td><strong>${escapeHtml(x.title)}</strong></td><td><span class="pill ${x.status==='published'?'success':'warning'}">${x.status==='published'?'Yayında':'Taslak'}</span></td><td>${formatMoment(x.updated_at)}</td></tr>`).join(''):'<tr><td colspan="4">Henüz bilgi bankası içeriği yok.</td></tr>';}catch(_){}}
document.querySelector('#knowledge-form')?.addEventListener('submit',async(e)=>{e.preventDefault(); const status=document.querySelector('#knowledge-status'); status.textContent='Kaydediliyor…'; const payload={language:document.querySelector('#knowledge-language').value,title:document.querySelector('#knowledge-title').value,content:document.querySelector('#knowledge-content').value,status:document.querySelector('#knowledge-published').checked?'published':'draft'}; try{const r=await fetch('/api/knowledge',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)}); const d=await r.json(); if(!r.ok)throw Error(d.error); status.textContent='Bilgi bankasına kaydedildi.'; loadKnowledge();}catch(err){status.textContent=err.message||'Bilgi bankası kaydedilemedi';}});
const sipForm = document.querySelector('#sip-form'); const sipStatus = document.querySelector('#sip-status'); let sipTenantId = 0;
async function loadSip() { try { const r=await fetch(`/api/admin/tenants/${sipTenantId}/sip`,{credentials:'same-origin'}); if(!r.ok)return; const d=await r.json(); document.querySelector('#sip-username').value=d.username||''; document.querySelector('#sip-did').value=d.did||d.username||''; document.querySelector('#sip-domain').value=d.domain||''; sipStatus.textContent=d.configured?`Kayıtlı parola: ${d.masked}`:'SIP parolası tanımlı değil'; } catch(_){} }
sipForm?.addEventListener('submit',async(e)=>{e.preventDefault(); sipStatus.textContent='Kaydediliyor…'; const payload={username:document.querySelector('#sip-username').value,did:document.querySelector('#sip-did').value,domain:document.querySelector('#sip-domain').value,password:document.querySelector('#sip-password').value}; try{const r=await fetch(`/api/admin/tenants/${sipTenantId}/sip`,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)}); const d=await r.json(); if(!r.ok)throw Error(d.error); document.querySelector('#sip-password').value=''; sipStatus.textContent=`Kaydedildi (${d.masked||'parola yok'})`;}catch(err){sipStatus.textContent=err.message||'Kayıt başarısız';}}); loadSip();

const customersBody=document.querySelector('#customers-body');
const customerForm=document.querySelector('#customer-form'); if(customerForm&&!document.querySelector('#customer-agreement')){const row=document.createElement('label');row.className='check';row.innerHTML='<input id="customer-agreement" type="checkbox" required> Kullanıcı sözleşmesi ve KVKK metinlerini müşteriye sundum ve onayını aldım';const submit=customerForm.querySelector('button[type="submit"]');submit?.parentNode.insertBefore(row,submit);}
function loadCustomers(items=[]) { if(!customersBody)return; customersBody.innerHTML=items.length?items.map(item=>`<tr><td><strong>${escapeHtml(item.name)}</strong></td><td>${escapeHtml(item.username)}</td><td>${escapeHtml(item.email||'—')}</td><td>${Number(item.credits||0).toFixed(2)}</td><td><span class="pill ${item.status==='active'?'success':'warning'}">${item.status==='active'?'Aktif':'Pasif'}</span></td><td><div class="password-reset"><input type="password" minlength="8" autocomplete="new-password" placeholder="Yeni parola" data-password-for="${item.id}"><button class="button secondary" type="button" data-reset-password="${item.id}">Değiştir</button></div></td></tr>`).join(''):'<tr><td colspan="6">Henüz müşteri hesabı yok.</td></tr>'; const selector=document.querySelector('#sip-tenant'); if(selector){selector.innerHTML=items.map(item=>`<option value="${item.id}">${escapeHtml(item.name)} (${escapeHtml(item.username)})</option>`).join(''); if(items.length){selector.value=String(sipTenantId); if(!selector.value)sipTenantId=items[0].id; loadSip();}} const creditSelector=document.querySelector('#credit-tenant'); if(creditSelector){creditSelector.innerHTML=items.map(item=>`<option value="${item.id}">${escapeHtml(item.name)} — ${Number(item.credits||0).toFixed(2)} kredi</option>`).join(''); if(items.length){creditSelector.value=String(creditTenantId); if(!creditSelector.value)creditTenantId=items[0].id;}} }
