document.querySelector('#customer-form')?.addEventListener('submit',async(e)=>{e.preventDefault(); const status=document.querySelector('#customer-status'); status.textContent='Hesap oluşturuluyor…'; const payload={name:document.querySelector('#customer-name').value,email:document.querySelector('#customer-email').value,username:document.querySelector('#customer-username').value,password:document.querySelector('#customer-password').value,credits:Number(document.querySelector('#customer-credits').value||0),agreement_accepted:Boolean(document.querySelector('#customer-agreement')?.checked)}; try{const r=await fetch('/api/admin/tenants',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)}); const d=await r.json(); if(!r.ok)throw Error(d.error); status.textContent=`${d.tenant.name} oluşturuldu. Kullanıcı: ${d.tenant.username}`; e.target.reset(); document.querySelector('#customer-credits').value='0'; loadOperationalData();}catch(err){status.textContent=err.message||'Müşteri oluşturulamadı';}});
customersBody?.addEventListener('click',async(e)=>{const button=e.target.closest('[data-reset-password]'); if(!button)return; const id=button.dataset.resetPassword; const input=customersBody.querySelector(`[data-password-for="${id}"]`); const password=input?.value||''; if(password.length<8){showToast('Parola en az 8 karakter olmalı.');return;} button.disabled=true; try{const r=await fetch(`/api/admin/tenants/${id}/password`,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({password})}); const d=await r.json(); if(!r.ok)throw Error(d.error); input.value=''; showToast('Müşteri parolası değiştirildi.');}catch(err){showToast(err.message||'Parola değiştirilemedi.');}finally{button.disabled=false;}});
function showToast(message){toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3000);}
