document.querySelector('.select-button')?.addEventListener('click',()=>{trafficRangeDays=trafficRangeDays===7?30:trafficRangeDays===30?90:7;const button=document.querySelector('.select-button');if(button)button.innerHTML=`Son ${trafficRangeDays} gün <span>⌄</span>`;const caption=document.querySelector('.chart-panel p');if(caption)caption.textContent=`Son ${trafficRangeDays} günün gerçek çağrı kayıtları`;loadOperationalData();});
reportButton?.addEventListener('click',async(e)=>{e.preventDefault();e.stopImmediatePropagation();reportButton.disabled=true;const original=reportButton.innerHTML;reportButton.textContent='Rapor hazırlanıyor…';try{const query=currentUser?.role==='admin'?('?tenant_id='+encodeURIComponent(dashboardTenantId)):'';const responses=await Promise.all([fetch('/api/calls'+query,{credentials:'same-origin'}),fetch('/api/appointments'+query,{credentials:'same-origin'})]);const calls=responses[0].ok?((await responses[0].json()).items||[]):[];const appointments=responses[1].ok?((await responses[1].json()).items||[]):[];const rows=[['Kayıt türü','Tarih','Müşteri/Arayan','Telefon','Hizmet','Süre','Kredi','Durum']];calls.forEach(x=>rows.push(['Çağrı',formatMoment(x.started_at),currentUser?.name||'Müşteri',x.caller||'','',formatDuration(x.started_at,x.ended_at),Number(x.billed_credits||0).toFixed(2),x.status||'']));appointments.forEach(x=>rows.push(['Randevu',formatMoment(x.appointment_at),x.customer_name||'',x.phone||'',x.service||'','','',x.status||'']));const csv='\\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\\r\\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='oim-rapor-'+new Date().toISOString().slice(0,10)+'.csv';a.click();URL.revokeObjectURL(url);showToast((calls.length+appointments.length)+' kayıt rapora aktarıldı.');}catch(err){showToast(err.message||'Rapor oluşturulamadı.');}finally{reportButton.disabled=false;reportButton.innerHTML=original;}},true);
