async function loadCustomerTelegram(){try{const r=await fetch('/api/tenant/telegram',{credentials:'same-origin'});if(!r.ok)return;const d=await r.json();const chat=document.querySelector('#customer-telegram-chat');const enabled=document.querySelector('#customer-telegram-enabled');const status=document.querySelector('#customer-telegram-status');if(chat)chat.value=d.chat_id||'';if(enabled)enabled.checked=Boolean(d.enabled);if(status)status.textContent=d.configured?`Kayıtlı token: ${d.masked}`:'Telegram botu tanımlı değil';}catch(_){} }
function ensureCrmControls(){const panel=document.querySelector('#crm');if(!panel||document.querySelector('#crm-filter'))return;const form=panel.querySelector('#contact-form');if(!form)return;const controls=document.createElement('div');controls.className='crm-toolbar';controls.innerHTML='<input id="crm-filter" placeholder="Ad soyada göre filtrele" aria-label="Ad soyada göre filtrele"><input id="crm-phone-filter" placeholder="Telefon" aria-label="Telefon filtresi"><input id="crm-email-filter" placeholder="E-posta" aria-label="E-posta filtresi"><select id="crm-sort" aria-label="CRM sıralama"><option value="updated">Son güncellenen</option><option value="name">Ada göre</option></select><button class="button outline" type="button" id="crm-filter-clear">Temizle</button><span class="form-note" id="crm-result-count"></span>';form.insertAdjacentElement('afterend',controls);const rerender=()=>{const sort=document.querySelector('#crm-sort')?.value||'updated';crmItems.sort((a,b)=>(sort==='name'?String(a.name||'').localeCompare(String(b.name||''),'tr'):Number(b.updated_at||0)-Number(a.updated_at||0)));renderContacts();const count=document.querySelector('#crm-result-count');if(count)count.textContent=`${document.querySelectorAll('#contacts-body tr').length} kayıt`};['#crm-filter','#crm-phone-filter','#crm-email-filter','#crm-sort'].forEach(sel=>document.querySelector(sel)?.addEventListener('input',rerender));document.querySelector('#crm-filter-clear')?.addEventListener('click',()=>{['#crm-filter','#crm-phone-filter','#crm-email-filter'].forEach(sel=>{const f=document.querySelector(sel);if(f)f.value='';});rerender();});}
ensureCrmControls();
function addTelegramTest(formId,endpoint,statusId){const form=document.querySelector(formId);if(!form||form.querySelector('[data-telegram-test]'))return;const button=document.createElement('button');button.type='button';button.className='button outline';button.dataset.telegramTest='1';button.textContent='Bağlantıyı test et';form.appendChild(button);button.addEventListener('click',async()=>{const status=document.querySelector(statusId);if(status)status.textContent='Telegram bağlantısı test ediliyor…';try{const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:'{}'});const d=await r.json();if(!r.ok)throw Error(d.error);if(status)status.textContent=`${d.bot_username} → ${d.chat_title} doğrulandı (${d.bot_status}).`;}catch(err){if(status)status.textContent=err.message||'Telegram bağlantısı test edilemedi.';}});}
addTelegramTest('#telegram-form','/api/admin/telegram/test','#telegram-status');addTelegramTest('#customer-telegram-form','/api/tenant/telegram/test','#customer-telegram-status');
const aiSettingsForm=document.querySelector('#ai-settings-form');
const aiSettingsFields=document.querySelector('#ai-settings-fields');
const aiGreeting=document.querySelector('#ai-greeting');
const aiSettingsStatus=document.querySelector('#ai-settings-status');
const agentSettingsCard=document.querySelector('.agents-panel');
if(agentSettingsCard){
  const shortcut=document.createElement('button');
  shortcut.type='button';
  shortcut.className='button secondary full';
  shortcut.dataset.customerOnly='';
  shortcut.hidden=true;
  shortcut.textContent='Açılış mesajını düzenle';
  shortcut.addEventListener('click',()=>{setView('opening-message');window.scrollTo({top:0,behavior:'smooth'});});
  agentSettingsCard.appendChild(shortcut);
}
let aiSettingsTenant=null;
let aiSettingsLoading=false;
function updateGreetingCount(){
  document.querySelector('#ai-greeting-count').textContent=`${aiGreeting.value.length} / 1000 karakter`;
}
async function loadAiSettings(force=false){
  if(!aiSettingsForm||currentUser?.role!=='customer'||aiSettingsLoading||(!force&&aiSettingsTenant===currentUser.id))return;
  const tenantId=currentUser.id;
  aiSettingsLoading=true;
  aiSettingsFields.disabled=true;
  aiSettingsStatus.textContent='Mesaj yükleniyor…';
  aiSettingsStatus.dataset.state='loading';
  document.querySelector('#ai-settings-retry').hidden=true;
  try{
    const r=await fetch('/api/tenant/ai-settings',{credentials:'same-origin'});
    const d=await r.json();
    if(!r.ok)throw Error(d.error||'Ayarlar yüklenemedi.');
    if(currentUser?.id!==tenantId)return;
    aiGreeting.value=d.greeting||'';
    document.querySelector('#ai-voice').value=d.voice||'alloy';
    document.querySelector('#ai-hours').value=d.working_hours||'';
    aiSettingsTenant=tenantId;
    updateGreetingCount();
    aiSettingsFields.disabled=false;
    aiSettingsStatus.dataset.state='ready';
    aiSettingsStatus.textContent=aiGreeting.value?'Kayıtlı açılış mesajınız yüklendi.':'Karşılama metninizi yazıp kaydedin.';
  }catch(err){
    aiSettingsStatus.dataset.state='error';
    aiSettingsStatus.textContent=err.message||'Mesaj yüklenemedi. Yeniden deneyin.';
    document.querySelector('#ai-settings-retry').hidden=false;
  }finally{aiSettingsLoading=false;}
}
document.querySelector('#ai-settings-retry')?.addEventListener('click',()=>loadAiSettings(true));
aiSettingsForm?.addEventListener('input',()=>{
  aiGreeting.setCustomValidity('');
  updateGreetingCount();
  aiSettingsStatus.dataset.state='dirty';
  aiSettingsStatus.textContent='Kaydedilmemiş değişiklikler var.';
});
aiSettingsForm?.addEventListener('submit',async(event)=>{
  event.preventDefault();
  if(aiSettingsFields.disabled||currentUser?.role!=='customer')return;
  if(!aiGreeting.value.trim()){
    aiGreeting.setCustomValidity('Lütfen bir karşılama metni yazın.');
    aiGreeting.reportValidity();
    return;
  }
  const payload={greeting:aiGreeting.value.trim(),voice:document.querySelector('#ai-voice').value,working_hours:document.querySelector('#ai-hours').value};
  aiSettingsFields.disabled=true;
  aiSettingsStatus.dataset.state='loading';
  aiSettingsStatus.textContent='Kaydediliyor…';
  aiSettingsForm.setAttribute('aria-busy','true');
  try{
    const r=await fetch('/api/tenant/ai-settings',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)});
    const d=await r.json();
    if(!r.ok)throw Error(d.error||'Mesaj kaydedilemedi.');
    aiGreeting.value=d.greeting;
    updateGreetingCount();
    aiSettingsStatus.dataset.state='success';
    aiSettingsStatus.textContent='Kaydedildi. Yeni çağrılar bu mesajla başlayacak.';
  }catch(err){
    aiSettingsStatus.dataset.state='error';
    aiSettingsStatus.textContent=err.message||'Mesaj kaydedilemedi. Metniniz korunuyor; yeniden deneyin.';
  }finally{
    aiSettingsFields.disabled=false;
    aiSettingsForm.setAttribute('aria-busy','false');
  }
});
const knowledgeContent=document.querySelector('#knowledge-content');if(knowledgeContent&&!document.querySelector('#knowledge-file')){const label=document.createElement('label');label.textContent='Markdown dosyası yükle';label.innerHTML+='<input id="knowledge-file" type="file" accept=".md,.markdown,text/markdown">';knowledgeContent.insertAdjacentElement('afterend',label);document.querySelector('#knowledge-file').addEventListener('change',(event)=>{const file=event.target.files?.[0];if(!file)return;if(!/\.(md|markdown)$/i.test(file.name)){showToast('Yalnızca .md veya .markdown dosyası yükleyin.');event.target.value='';return;}if(file.size>512000){showToast('Bilgi bankası dosyası 500 KB altında olmalı.');event.target.value='';return;}const reader=new FileReader();reader.onload=()=>{knowledgeContent.value=String(reader.result||'');const title=document.querySelector('#knowledge-title');if(title&&!title.value)title.value=file.name.replace(/\.(md|markdown)$/i,'');};reader.readAsText(file,'UTF-8');});}
const crmObserver=new MutationObserver(()=>document.querySelectorAll('#contacts-body tr').forEach(row=>{const action=row.querySelector('.crm-actions');if(action&&!action.querySelector('[data-detail-contact]')){const name=row.querySelector('strong')?.textContent||'';const item=crmItems.find(x=>x.name===name);if(item){const button=document.createElement('button');button.className='button outline';button.type='button';button.dataset.detailContact=item.id;button.textContent='Detay';action.prepend(button);}}}));
const crmBody=document.querySelector('#contacts-body');if(crmBody)crmObserver.observe(crmBody,{childList:true,subtree:true});
document.querySelector('#contacts-body')?.addEventListener('click',async(event)=>{const button=event.target.closest('[data-detail-contact]');if(!button)return;const id=Number(button.dataset.detailContact);const r=await fetch('/api/contacts/'+id,{credentials:'same-origin'});const d=await r.json();if(!r.ok){showToast(d.error||'Detay alınamadı.');return;}const callText=d.calls.length?d.calls.map(x=>`${formatMoment(x.started_at)} — ${x.status} — ${Number(x.billed_credits||0).toFixed(2)} kredi`).join('\n'):'Çağrı kaydı yok';const apptText=d.appointments.length?d.appointments.map(x=>`${x.appointment_at} — ${x.service} — ${x.status}`).join('\n'):'Randevu yok';alert(`${d.contact.name}\n\nNot: ${d.contact.notes||'—'}\n\nÇağrılar:\n${callText}\n\nRandevular:\n${apptText}`);});
